```java
try {
    System.out.println("try");
    int x = 10 / 0; // ArithmeticException
    System.out.println("after exception"); // never prints
} catch (ArithmeticException e) {
    System.out.println("catch");
} finally {
    System.out.println("finally");
}
// Output: try → catch → finally
```

```java
Connection conn = getConnection();
try {
    // do database work — exception propagates to caller
    executeQuery(conn);
} finally {
    conn.close(); // always closes, even if exception thrown
}
```

```java
public static int test() {
    try {
        return 1;
    } finally {
        return 2; // overrides the try's return 1
    }
}
// test() returns 2, not 1

public static int danger() {
    try {
        throw new RuntimeException();
    } finally {
        return 99; // exception is SILENTLY SWALLOWED
    }
}
// danger() returns 99, exception is lost!
```

```java
// WRONG: compile error — IOException unreachable
try { riskyMethod(); }
catch (Exception e) { handle(e); }      // catches everything
catch (IOException e) { handle(e); }   // unreachable!

// CORRECT: specific before general
try { riskyMethod(); }
catch (IOException e) { handleIO(e); }     // specific first
catch (Exception e) { handleGeneral(e); }  // general last
```

```java
try {
    throw new IOException("original");
} catch (IOException e) {
    System.out.println("catch");
    // Bad: original exception is lost
    throw new RuntimeException("new exception");
    // Good: preserve original
    // throw new RuntimeException("new", e);
} finally {
    System.out.println("finally"); // still runs
}
```
